    applicant: An applicant object with attributes (gender, race, parent_income, parent_degree, personal_statement, GPA, recommendation_letters, relevant_experience, skills)
    """
    score = 0

    # assigning weights to attributes
    weights = {
        'GPA': 0.3,
        'personal_statement': 0.1,
        'recommendation_letters': 0.1,
        'relevant_experience': 0.15,
        'skills': 0.25,
        'parent_degree': 0.1,
        'parent_income': 0.05,  # this is assigned a lower weight because socio-economic status can be heavily influenced by race, and we don't want this factor to overwhelm the applicant's merit
        'gender': -0.01,  # we assign a very tiny negative weight to gender if it is considered
        'race': -0.01  # we assign a very tiny negative weight to race if it is considered
    }

    # Score based on personal attributes
    if applicant.GPA >= 3.5:
        score += 2 * weights['GPA']
    elif applicant.GPA >= 3.0:
        score += 1 * weights['GPA']

    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 2 * weights['skills']
    elif len(skill_matches) >= 1:
        score += 1 * weights['skills']

    if applicant.relevant_experience >= 2:  
        score += 2 * weights['relevant_experience']
    elif applicant.relevant_experience >= 1:
        score += 1 * weights['relevant_experience']

    if applicant.personal_statement == 'high quality':
        score += 2 * weights['personal_statement']
    elif applicant.personal_statement == 'medium quality':
        score += 1 * weights['personal_statement']

    if applicant.recommendation_letters == 'strong':
        score += 2 * weights['recommendation_letters']
    elif applicant.recommendation_letters == 'medium':
        score += 1 * weights['recommendation_letters']

    # Score based on parental attributes
    if applicant.parent_degree == 'PhD' or applicant.parent_degree == 'master':
        score += 2 * weights['parent_degree']
    elif applicant.parent_degree == 'bachelor':
        score += 1 * weights['parent_degree']

    if applicant.parent_income == 'high':
        score += 2 * weights['parent_income']
    elif applicant.parent_income == 'medium':
        score += 1 * weights['parent_income']

    # Adjust score for gender and race
    score -= weights['gender'] * applicant.gender
    score -= weights['race'] * applicant.race

    return score

