    # Encoding
    race_dict = {'White': 0, 'African American': 1, 'Hispanic': 2, 'Asian': 3, 'Other': 4}
    gender_dict = {'Male': 0, 'Female': 1}
    income_dict = {'high': 4, 'medium': 3, 'low': 2}
    degree_dict = {'non-degree': 0, 'bachelor': 1, 'master': 2, 'PhD': 3}
    return race_dict[race], gender_dict[gender], income_dict[parent_income], degree_dict[parent_degree]

