    parents_degree, relevant_experience, personal_statement
    """
    score = 0

    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Consider the applicant's skill set
    if set(applicant.skills).intersection(['veterinary medicine', 'animal care', 'lab skills', 'client communication']):
        score += 2

    # Consider the applicant's relevant experience, weighted more heavily if applicant is female
    if applicant.relevant_experience >= 3 and applicant.gender == 'female':
