    """
    Evaluate candidates for equestrian/equine studies major admission.
    applicant: An applicant object with attributes (skills, GPA, recommendation_letters, gender, race, parents_income, parent_degree, relevant_experience, personal_statement)
    """
    score = 0
    # GPA
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Skills
    relevant_skills = ['equestrian management', 'equine health', 'horse behavior', 'equine biology']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 3
    elif len(skill_matches) >= 1:
        score += 1

    # Recommendation Letters
    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Parents' income and degree
    if applicant.parent_income == 'high':
        score += 2
    elif applicant.parent_income == 'medium':
        score += 1
    if applicant.parent_degree in ["bachelor", "master", "PhD"]:  
        score += 1

    # relevan_experience
    if applicant.relevant_experience >= 2:
        score += 3
    elif applicant.relevant_experience >= 1:
        score += 2

    # Personal statement
    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # To try and reduce bias, we might want to apply a few rules to alleviate the issues surrounding the attributes of race, gender.
    # It is typically not a good idea to outright disqualify, but we can reduce scores.
    # For example, below is a rule to not increase score based on applicants' race or gender:
    if applicant.race in ['black', 'hispanic', 'native american']:
        if score > 0:
            score -= 2
    if applicant.gender == 'female':
        score -= 1

    return max(0, score)

