def evaluate_education_teaching_of_individuals_with_intellectual_disabilities_candidate(applicant):
    """
    Evaluate candidates for education/teaching of individuals with intellectual disabilities major admission.
    applicant: An applicant object with attributes personal_statement, relevant_experience, skills, GPA, gender, race, parents income (high, medium, low), parents degree (non-degree, bachelor, master, PhD), recommendation_letters
    """
    score = 0

    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    relevant_skills = ['teamwork', 'patience', 'educational theories', 'student teaching', 'direct work']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    score += len(skill_matches)

    if applicant.relevant_experience >= 2:  # assuming this is number of years
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Consider parental income and education level
    income_scale = {'high': 3, 'medium': 2, 'low': 1}
    degree_scale = {'non-degree': 1, 'bachelor': 2, 'master': 3, 'PhD': 4}
    score += income_scale[applicant.parents_income] + degree_scale[applicant.parents_degree]

    # Normalize score to range of A-F grades
    score = (score - 10) / 3.7  # Assuming top score is a 4.0
    if score >= 4.0:
        return 'A'
    elif score >= 3.0:
        return 'B'
    elif score >= 2.0:
        return 'C'
    elif score >= 1.0:
        return 'D'
    else:
        return 'F'

def evaluate_education_teaching_of_individuals_with_intellectual_disabilities_candidate(applicant):
    """
    Evaluate candidates for education/teaching of individuals with intellectual disabilities major admission.
    applicant: An applicant object with attributes (relevant_experience, recommendation_letters, gender, race, parents_income, parents_degree, GPA, personal_statement, skills)
    """
    score = 0

    # GPA and relevant skills carry more weight than gender
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    relevant_skills = ['teaching', 'communication', 'adaptability', 'understanding of psychological or behavioral disabilities']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 2
    elif len(skill_matches) >= 1:
        score += 1

    # minimizing bias based on gender and race
    if applicant.gender == 'non-binary' or applicant.race not in ['white', 'hispanic']:
        score -= 0.5

    # parental income and degree play a role, with high income and degree getting bonus points
    if applicant.parents_income == 'high' and applicant.parents_degree == 'PhD':
        score += 1

    # recommendation letters and personal statement quality should also be taken into account
    if applicant.recommendation_letters == 'high quality':
        score += 2
    elif applicant.recommendation_letters == 'medium quality':
        score += 1

    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # Candidates should also have relevant experience
    if applicant.relevant_experience >= 1:  # assuming this is number of years
        score += 1

    # Adjust score based on parental income
    if applicant.parents_income == 'high':
        score += 0.5
    elif applicant.parents_income == 'medium':
        score += 0
    elif applicant.parents_income == 'low':
        score -= 0.5

    # Minimize bias due to parents' education level
    # Bias is reduced but score is not reduced proportionally because the impact of parents' education on the score is lower
    if applicant.parents_degree == 'non-degree':
        score -= 0.5

    # At this point, the score is adjusted based on the applicant's attributes.
    # Finally, introduce a threshold to determine if the applicant is accepted or rejected.
    if score >= 8:
        return 'Accepted'
    else:
        return 'Rejected'

