def evaluate_early_childhood_and_family_studies_candidate(applicant):
    """
    Evaluate candidates for early childhood and family studies major admission.
    applicant: An applicant object with attributes: personal_statement, GPA, gender, race, parents_income, parents_degree, recommendation_letters, skills, relevant_experience
    """
    score = 0
    personal_statement_scores = {'high quality': 2, 'medium quality': 1, 'low quality': 0}
    gpa_scores = {True: 2, False: 1}
    gender_scores = {'male': 1, 'female': 1, 'non-binary': 1, 'prefer not to say': 0}
    race_scores = {'white': 1, 'black': 1, 'asian': 1, 'hispanic': 1, 'prefer not to say': 0}
    parents_income_scores = {'high': 3, 'medium': 2, 'low': 1}
    parents_degree_scores = {'non-degree': 0, 'bachelor': 1, 'master': 2, 'PhD': 3}
    recommendation_letter_scores = {0: 0, 1: 1, 2: 1, 3: 2, 4: 2}
    skills_scores = {'early childhood education': 1, 'child psychology': 2, 'social work': 1, 'family studies': 2}

    score += personal_statement_scores[applicant.personal_statement]
    score += gpa_scores[applicant.GPA >= 3.5]
    score += gender_scores[applicant.gender]
    score += race_scores[applicant.race]
    score += parents_income_scores[applicant.parents_income]
    score += parents_degree_scores[applicant.parents_degree]
    score += recommendation_letter_scores[applicant.recommendation_letters]

    skill_matches = [skill for skill in applicant.skills if skill in skills_scores]
    score += len(skill_matches) * skills_scores[skill_matches[0]]

    score += applicant.relevant_experience

    return score

def evaluate_early_childhood_and_family_studies_candidate(applicant):
    """
    Evaluate candidates for early childhood and family studies major admission.
    applicant: An applicant object with attributes gender, race, parents income (high, medium, low),
    parents degree (non-degree, bachelor, master, PhD), personal_statement, GPA, recommendation_letters, 
    relevant_experience, skills
    """

    # Mapping parents degree to numerical values
    parent_degree_scores = {'non-degree': 1, 'bachelor': 2, 'master': 3, 'PhD': 4}

    # Initializing score
    score = 0

    # Adding points for parent's degree if it exists
    if applicant.parents_degree in parent_degree_scores:
        score += parent_degree_scores[applicant.parents_degree]

    # Mapping income to numerical values
    income_scores = {'high': 4, 'medium': 3, 'low': 2}

    # Adding points for income if it exists
    if applicant.parents_income in income_scores:
        score += income_scores[applicant.parents_income]

    # Mapping GPA and personal statement quality to numerical values
    if applicant.GPA >= 3.5:
        score += 4
    elif applicant.GPA >= 3.0:
        score += 3
    elif applicant.GPA >= 2.5:
        score += 2
    elif applicant.GPA >= 2.0:
        score += 1

    # Assuming personal_statement has two qualities: 'high quality' and 'medium quality'
    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # Adding points for relevant experience
    if applicant.relevant_experience >= 2:
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

    # Considering skills if they exist
    if hasattr(applicant, 'skills'):
        skill_scores = {'teacher': 2, 'early childhood education': 3, 'family studies': 2}
        # If the skill is in the skill_scores dictionary and the skill count is above or equal to the score, add score to total
        matching_skills = [skill for skill in applicant.skills if skill in skill_scores and applicant.skills[skill] >= skill_scores[skill]]
        score += len(matching_skills)

    # Considering recommendation letters if they exist
    if hasattr(applicant, 'recommendation_letters'):
        if applicant.recommendation_letters == 'strong':
            score += 2
        elif applicant.recommendation_letters == 'medium':
            score += 1

    return score

